import React, { Component, Fragment } from "react";
import { MDBDataTable, MDBBtn } from "mdbreact";
import { Card, CardBody, CardHeader, Button, Input } from "reactstrap";
import {
  MdAddCircle,
  MdCheckCircle,
  MdEdit,
  MdRemoveCircle
} from "react-icons/md";
import { connect } from "react-redux";

class Clients extends Component {
  state = {
    addRow: false,
    rowData: [
      {
        id: "Garrett Winters",
        name: "Accountant",
        createdBy: "Tokyo",
        actions: (
          <div>
            <Button className="float-left" color="dark" onClick={this.addRow}>
              <MdEdit />
            </Button>
            <Button className="float-left" color="dark" onClick={this.addRow}>
              <MdRemoveCircle />
            </Button>
          </div>
        )
      }
    ]
  };
  addRow = () => {
    console.log("adddrsssw");
    this.setState(state => ({
      addRow: !state.addRow,
      rowData: state.rowData.push(1)
    }));
  };
  render() {
    const data = {
      columns: [
        {
          label: "Id",
          field: "id",
          sort: "asc"
        },
        {
          label: "Name",
          field: "name",
          sort: "asc"
        },
        {
          label: "CreatedBy",
          field: "createdBy",
          sort: "asc"
        },
        {
          label: "Actions",
          field: "actions",
          sort: "asc"
        }
      ],
      rows: this.state.rowData
    };

    return (
      <Card>
        <CardHeader>
          <h4 className="float-left">Clients</h4>
          <Button className="float-right" color="dark" onClick={this.addRow}>
            <MdAddCircle />
          </Button>
        </CardHeader>
        <CardBody>
          <MDBDataTable striped bordered hover data={data} />
        </CardBody>
      </Card>
    );
  }
}

const mapStateToProps = state => ({
  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

export default connect(mapStateToProps, null)(Clients);
